#!/usr/bin/env bash
# Records what the API answers to a fixed sequence of requests, normalised so two runs against the same
# build give the same file: snapshot-api.sh <base-url> <out-file>. Diff a snapshot from before a change
# (an upgrade, a refactoring) against one from after it to see every user-visible difference.
# Normalised: ids and e-mails become placeholders, digits in date-like strings become 9 (the format is
# kept, the value isn't), versions and messages generated by Spring or Jackson (marked fw) become
# placeholders. Status, Content-Type, keys and key order are kept as they are. Needs curl and jq.
set -euo pipefail

[ $# -eq 2 ] || { echo "usage: $0 <base-url> <out-file>" >&2; exit 2; }
base="$1"
out="$2"
run="$(date +%s)-$RANDOM"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
: > "$out"

normalise='
def shape:
  if type == "string" then
    if test("^[0-9]{4}-[0-9]{2}-[0-9]{2}") then gsub("[0-9]"; "9")
    elif test("^[0-9]{1,2}/[0-9]{1,2}/[0-9]{2}, [0-9]{1,2}:[0-9]{2} (AM|PM)$") then "<us-short>"
    else . end
  else . end;
walk(if type == "object" then with_entries(
       if (.key == "id" or .key == "speakerId" or .key == "talkId") and (.value | type) == "number" then .value = "<id>"
       elif .key == "email" then .value = "<email>"
       elif .key == "coSpeakerIds" then .value |= map("<id>")
       elif .key == "path" and (.value | type) == "string" then .value |= gsub("[0-9]+"; "<n>")
       else . end)
     else shape end)
| if $fw == "fw" and type == "object" and has("message") then .message = "<framework-message>" else . end
| if type == "object" and has("versions") then .versions |= map_values("<version>") else . end
| if type == "object" and has("version") then .version = "<version>" else . end'

# req <label> <method> <path> [body] [content-type] [fw]: label is the path as written in the snapshot
req() {
    local label="$1" method="$2" path="$3" body="${4-}" type="${5:-application/json}" fw="${6-}"
    local args=(-sS -o "$tmp/body" -w '%{http_code} %{content_type}' -X "$method" -H "Content-Type: $type")
    [ -n "$body" ] && args+=(--data-binary "$body")
    local meta
    meta="$(curl "${args[@]}" "$base$path")"
    {
        echo "### $method $label${body:+ $(echo "$body" | sed -E 's/"email":"[^"]*"/"email":"<email>"/; s/"speakerId":[0-9]+/"speakerId":<id>/')}"
        echo "$meta"
        if [ -s "$tmp/body" ] && jq -e . "$tmp/body" > /dev/null 2>&1; then
            jq -c --arg fw "$fw" "$normalise" "$tmp/body"
        else
            sed -E 's/[0-9]+/<n>/g' "$tmp/body"
            echo
        fi
    } >> "$out"
}

id() {
    jq -r .id "$tmp/body"
}

speaker() {
    req "/speakers" POST /speakers "{\"name\":\"$1\",\"email\":\"$1-$run@example.test\"}"
    id
}

talk() {
    req "/talks" POST /talks "{\"title\":\"$2\",\"format\":\"$3\",\"level\":\"BEGINNER\",\"speakerId\":$1}"
    id
}

# Speakers
a="$(speaker ada)"
b="$(speaker barbara)"
req "/speakers/" POST /speakers/ "{\"name\":\"Carl\",\"email\":\"carl-$run@example.test\",\"bio\":\"Trailing slash\"}"
req "/speakers (comment)" POST /speakers "/* a comment */ {\"name\":\"Dag\",\"email\":\"dag-$run@example.test\"}"
req "/speakers (duplicate e-mail)" POST /speakers "{\"name\":\"Ada\",\"email\":\"ADA-$run@example.test\"}"
req "/speakers (blank name)" POST /speakers "{\"name\":\"\",\"email\":\"eve-$run@example.test\"}" application/json fw
req "/speakers (bio too long)" POST /speakers "{\"name\":\"Eve\",\"email\":\"eve-$run@example.test\",\"bio\":\"$(printf 'x%.0s' $(seq 1 501))\"}" application/json fw
req "/speakers/{a}" GET "/speakers/$a"
req "/speakers/{a}/" GET "/speakers/$a/"
req "/speakers/999999" GET /speakers/999999
req "/speakers/abc" GET /speakers/abc "" application/json fw

# Talks
t="$(talk "$a" "Presentation" PRESENTATION)"
req "/talks (durationMinutes ignored)" POST /talks "{\"title\":\"Lightning\",\"format\":\"LIGHTNING_10\",\"level\":\"ADVANCED\",\"speakerId\":$a,\"durationMinutes\":999}"
talk "$a" "Workshop" WORKSHOP > /dev/null
req "/talks (fourth talk)" POST /talks "{\"title\":\"Fourth\",\"format\":\"LIGHTNING_20\",\"level\":\"BEGINNER\",\"speakerId\":$a}"
req "/talks (bad format)" POST /talks "{\"title\":\"X\",\"format\":\"KEYNOTE\",\"level\":\"BEGINNER\",\"speakerId\":$b}"
req "/talks (bad level)" POST /talks "{\"title\":\"X\",\"format\":\"WORKSHOP\",\"level\":\"beginner\",\"speakerId\":$b}"
req "/talks (blank title)" POST /talks "{\"title\":\"  \",\"format\":\"WORKSHOP\",\"level\":\"BEGINNER\",\"speakerId\":$b}"
req "/talks (unknown speaker)" POST /talks "{\"title\":\"X\",\"format\":\"WORKSHOP\",\"level\":\"BEGINNER\",\"speakerId\":999999}"
req "/talks/{t}" GET "/talks/$t"
req "/talks/{t}/" GET "/talks/$t/"
req "/talks?speakerId={a}" GET "/talks?speakerId=$a"
req "/talks?sort=bad" GET "/talks?sort=bad"
req "/speakers/{a}/talks" GET "/speakers/$a/talks"
req "/speakers/{a}/talks/" GET "/speakers/$a/talks/"

# Co-speakers
req "/talks/{t}/co-speakers/{b}" PUT "/talks/$t/co-speakers/$b"
req "/talks/{t}/co-speakers/{b} (again)" PUT "/talks/$t/co-speakers/$b"
req "/talks/{t}/co-speakers/{a} (main speaker)" PUT "/talks/$t/co-speakers/$a"
req "/talks/{t}/co-speakers/999999" PUT "/talks/$t/co-speakers/999999"
req "/speakers/{b}/talks" GET "/speakers/$b/talks"
req "/talks/{t}/co-speakers/{b}" DELETE "/talks/$t/co-speakers/$b"
req "/talks/{t}/co-speakers/{b} (again)" DELETE "/talks/$t/co-speakers/$b"

# Ratings
req "/talks/{t}/ratings/1" PUT "/talks/$t/ratings/1" '{"score":4}'
req "/talks/{t}/ratings/2" PUT "/talks/$t/ratings/2" '{"score":5}'
req "/talks/{t}/ratings/2 (change)" PUT "/talks/$t/ratings/2" '{"score":3}'
req "/talks/{t}/ratings/3 (score 6)" PUT "/talks/$t/ratings/3" '{"score":6}'
req "/talks/{t}/ratings/3 (score \"3\")" PUT "/talks/$t/ratings/3" '{"score":"3"}'
req "/talks/{t}/ratings/3 (score 3.5)" PUT "/talks/$t/ratings/3" '{"score":3.5}'
req "/talks/{t}/ratings/3 (no score)" PUT "/talks/$t/ratings/3" '{}'
req "/talks/{t}/ratings/3 (trailing tokens)" PUT "/talks/$t/ratings/3" '{"score":3} x' application/json fw
req "/talks/{t}/ratings/0" PUT "/talks/$t/ratings/0" '{"score":3}'
req "/talks/999999/ratings/1" PUT /talks/999999/ratings/1 '{"score":3}'
req "/talks/{t} (rated)" GET "/talks/$t"
req "/talks?sort=rating&speakerId={a}" GET "/talks?sort=rating&speakerId=$a"

# Errors Spring and Jackson generate
req "/talks (bad JSON)" POST /talks 'not json' application/json fw
req "/talks (text/plain)" POST /talks 'x' text/plain fw
req "/talks/{t}/ratings/1 (no body)" PUT "/talks/$t/ratings/1" "" application/json fw
req "/talks/abc" GET /talks/abc "" application/json fw
req "/talks" DELETE /talks "" application/json fw
req "/nope" GET /nope "" application/json fw

# Operations
req "/health" GET /health
req "/actuator/info" GET /actuator/info
